// Generated blocks work directly on the interpreter's CPU state, so the two
// can hand over to each other at any block boundary.

#ifndef IROBOT_RC_RUNTIME_H
#define IROBOT_RC_RUNTIME_H

#include <stdbool.h>
#include <stdint.h>

#include "../../third_party/mc6809/mc6809.h"

// A block returns the next block to run, or NULL with C.PC set.
typedef void *(*rc_block_t)(void);

extern mc6809__t ir_cpu;
extern uint32_t rc_limit;               // run until Clock reaches this
extern uint8_t ir_prog_bank;            // bank mapped at $4000, 0-5 (or 6-7: none)
extern const rc_block_t rc_fixed[0xA000];
extern const rc_block_t rc_banked[6][0x2000];

#ifdef RC_SELFTEST
extern uint8_t rc_test_mem[0x10000];
#define ir_ram0 rc_test_mem
#else
extern uint8_t ir_ram0[0x800];          // $0000-$07FF, always mapped
#endif

#define C ir_cpu
#define CLK(n) (C.Clock += (n))
#define OUT_OF_TIME() ((int32_t)(C.Clock - rc_limit) >= 0)

static inline uint8_t RD(uint16_t a)
{
    const uint8_t *p = C.ReadPointer[a >> 8];
    if (p)
        return p[a & 0xFF];
    return C.ReadFunction[a >> 8](a);
}

static inline void WR(uint16_t a, uint8_t v)
{
    uint8_t *p = C.WritePointer[a >> 8];
    if (p)
        p[a & 0xFF] = v;
    else
        C.WriteFunction[a >> 8](a, v);
}

static inline uint16_t RD16(uint16_t a)
{
    uint8_t hi = RD(a);
    return (uint16_t)(hi << 8 | RD((uint16_t)(a + 1)));
}

static inline void WR16(uint16_t a, uint16_t v)
{
    WR(a, (uint8_t)(v >> 8));
    WR((uint16_t)(a + 1), (uint8_t)v);
}

#define PUSH8(sp, v)  do { sp = (uint16_t)(sp - 1); WR(sp, (v)); } while (0)
#define PUSH16(sp, v) do { uint16_t v_ = (v); PUSH8(sp, (uint8_t)v_); PUSH8(sp, (uint8_t)(v_ >> 8)); } while (0)

static inline uint8_t rc_pull8(uint16_t *sp)
{
    uint8_t v = RD(*sp);
    *sp = (uint16_t)(*sp + 1);
    return v;
}

static inline uint16_t rc_pull16(uint16_t *sp)
{
    uint8_t hi = rc_pull8(sp);
    return (uint16_t)(hi << 8 | rc_pull8(sp));
}

#define PULL8(sp)  rc_pull8(&(sp))
#define PULL16(sp) rc_pull16(&(sp))

static inline uint8_t rc_get_cc(void)
{
    return (uint8_t)(C.CC_C | C.CC_V << 1 | C.CC_Z << 2 | C.CC_N << 3 |
                     C.CC_I << 4 | C.CC_H << 5 | C.CC_F << 6 | C.CC_E << 7);
}

static inline void rc_set_cc(uint8_t r)
{
    C.CC_C = r & 1;
    C.CC_V = (r >> 1) & 1;
    C.CC_Z = (r >> 2) & 1;
    C.CC_N = (r >> 3) & 1;
    C.CC_I = (r >> 4) & 1;
    C.CC_H = (r >> 5) & 1;
    C.CC_F = (r >> 6) & 1;
    C.CC_E = (r >> 7) & 1;
}

// Control transfer to an address only known at run time.
#ifdef RC_SELFTEST
static inline void *rc_dispatch(uint16_t pc)
{
    C.PC.w = pc;
    return 0;
}
#else
static inline void *rc_dispatch(uint16_t pc)
{
    rc_block_t b = 0;
    if (pc >= 0x6000)
        b = rc_fixed[pc - 0x6000];
    else if (pc >= 0x4000 && ir_prog_bank < 6)
        b = rc_banked[ir_prog_bank][pc - 0x4000];
    if (!b)
        C.PC.w = pc;
    return (void *)b;
}
#endif

// ---------------------------------------------------------------------------
// Flags
// ---------------------------------------------------------------------------

static inline void rc_tst(uint8_t v)
{
    C.CC_N = v >> 7;
    C.CC_Z = (v == 0);
    C.CC_V = 0;
}

static inline void rc_tst16(uint16_t v)
{
    C.CC_N = v >> 15;
    C.CC_Z = (v == 0);
    C.CC_V = 0;
}

static inline uint8_t rc_neg(uint8_t s)
{
    uint8_t r = (uint8_t)-s;
    C.CC_N = r >> 7;
    C.CC_Z = (r == 0);
    C.CC_V = (s == 0x80);
    C.CC_C = (s != 0);
    return r;
}

static inline uint8_t rc_com(uint8_t s)
{
    uint8_t r = (uint8_t)~s;
    C.CC_N = r >> 7;
    C.CC_Z = (r == 0);
    C.CC_V = 0;
    C.CC_C = 1;
    return r;
}

static inline uint8_t rc_lsr(uint8_t s)
{
    uint8_t r = s >> 1;
    C.CC_N = 0;
    C.CC_Z = (r == 0);
    C.CC_C = s & 1;
    return r;
}

static inline uint8_t rc_ror(uint8_t s)
{
    uint8_t r = (uint8_t)(s >> 1 | C.CC_C << 7);
    C.CC_N = r >> 7;
    C.CC_Z = (r == 0);
    C.CC_C = s & 1;
    return r;
}

static inline uint8_t rc_asr(uint8_t s)
{
    uint8_t r = (uint8_t)((s >> 1) | (s & 0x80));
    C.CC_N = r >> 7;
    C.CC_Z = (r == 0);
    C.CC_C = s & 1;
    return r;
}

static inline uint8_t rc_asl(uint8_t s)
{
    uint8_t r = (uint8_t)(s << 1);
    C.CC_N = r >> 7;
    C.CC_Z = (r == 0);
    C.CC_V = ((s ^ r) >> 7) & 1;
    C.CC_C = s >> 7;
    return r;
}

static inline uint8_t rc_rol(uint8_t s)
{
    uint8_t r = (uint8_t)(s << 1 | C.CC_C);
    C.CC_N = r >> 7;
    C.CC_Z = (r == 0);
    C.CC_V = ((s ^ r) >> 7) & 1;
    C.CC_C = s >> 7;
    return r;
}

static inline uint8_t rc_dec(uint8_t s)
{
    uint8_t r = (uint8_t)(s - 1);
    C.CC_N = r >> 7;
    C.CC_Z = (r == 0);
    C.CC_V = (s == 0x80);
    return r;
}

static inline uint8_t rc_inc(uint8_t s)
{
    uint8_t r = (uint8_t)(s + 1);
    C.CC_N = r >> 7;
    C.CC_Z = (r == 0);
    C.CC_V = (s == 0x7F);
    return r;
}

static inline uint8_t rc_sub(uint8_t d, uint8_t s)
{
    unsigned r = (unsigned)d - s;
    C.CC_N = (r >> 7) & 1;
    C.CC_Z = ((uint8_t)r == 0);
    C.CC_C = (r >> 8) & 1;
    C.CC_V = (((d ^ s) & (d ^ r)) >> 7) & 1;
    return (uint8_t)r;
}

static inline void rc_cmp(uint8_t d, uint8_t s)
{
    (void)rc_sub(d, s);
}

static inline uint8_t rc_sbc(uint8_t d, uint8_t s)
{
    unsigned r = (unsigned)d - s - C.CC_C;
    C.CC_N = (r >> 7) & 1;
    C.CC_Z = ((uint8_t)r == 0);
    C.CC_C = (r >> 8) & 1;
    C.CC_V = (((d ^ s) & (d ^ r)) >> 7) & 1;
    return (uint8_t)r;
}

static inline uint8_t rc_and(uint8_t d, uint8_t s)
{
    uint8_t r = d & s;
    rc_tst(r);
    return r;
}

static inline uint8_t rc_eor(uint8_t d, uint8_t s)
{
    uint8_t r = d ^ s;
    rc_tst(r);
    return r;
}

static inline uint8_t rc_or(uint8_t d, uint8_t s)
{
    uint8_t r = d | s;
    rc_tst(r);
    return r;
}

static inline uint8_t rc_adc(uint8_t d, uint8_t s)
{
    unsigned r = (unsigned)d + s + C.CC_C;
    C.CC_H = ((d ^ s ^ r) >> 4) & 1;
    C.CC_N = (r >> 7) & 1;
    C.CC_Z = ((uint8_t)r == 0);
    C.CC_C = (r >> 8) & 1;
    C.CC_V = ((~(d ^ s) & (d ^ r)) >> 7) & 1;
    return (uint8_t)r;
}

static inline uint8_t rc_add(uint8_t d, uint8_t s)
{
    unsigned r = (unsigned)d + s;
    C.CC_H = ((d ^ s ^ r) >> 4) & 1;
    C.CC_N = (r >> 7) & 1;
    C.CC_Z = ((uint8_t)r == 0);
    C.CC_C = (r >> 8) & 1;
    C.CC_V = ((~(d ^ s) & (d ^ r)) >> 7) & 1;
    return (uint8_t)r;
}

static inline uint16_t rc_sub16(uint16_t d, uint16_t s)
{
    uint32_t r = (uint32_t)d - s;
    C.CC_N = (r >> 15) & 1;
    C.CC_Z = ((uint16_t)r == 0);
    C.CC_C = (r >> 16) & 1;
    C.CC_V = (((d ^ s) & (d ^ r)) >> 15) & 1;
    return (uint16_t)r;
}

static inline void rc_cmp16(uint16_t d, uint16_t s)
{
    (void)rc_sub16(d, s);
}

static inline uint16_t rc_add16(uint16_t d, uint16_t s)
{
    uint32_t r = (uint32_t)d + s;
    C.CC_N = (r >> 15) & 1;
    C.CC_Z = ((uint16_t)r == 0);
    C.CC_C = (r >> 16) & 1;
    C.CC_V = ((~(d ^ s) & (d ^ r)) >> 15) & 1;
    return (uint16_t)r;
}

static inline void rc_daa(void)
{
    uint8_t msn = C.A >> 4, lsn = C.A & 0x0F, cf = 0;
    bool h = C.CC_H, c = C.CC_C;
    if (c || msn > 9 || (msn > 8 && lsn > 9))
        cf |= 0x60;
    if (h || lsn > 9)
        cf |= 0x06;
    C.A = rc_add(C.A, cf);
    C.CC_H = h;
    C.CC_C = C.CC_C | c;
    C.CC_V = 0;
}

// Self test (tools/recomp/selftest.c)
typedef struct
{
    rc_block_t fn;
    uint8_t code[6];
    int length;
    const char *text;
} rc_selftest_t;

#endif
